CREATE TYPE "GiftCodeRewardType" AS ENUM ('WALLET','GROUP_POINTS');
ALTER TABLE "User" ADD COLUMN "isSuspended" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "suspendedAt" TIMESTAMP(3), ADD COLUMN "suspensionReason" TEXT;
ALTER TABLE "TelegramGroup" ADD COLUMN "isSuspended" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "suspendedAt" TIMESTAMP(3), ADD COLUMN "suspensionReason" TEXT;
CREATE TABLE "GiftCode" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"rewardType" "GiftCodeRewardType" NOT NULL DEFAULT 'WALLET',"cashAmount" BIGINT NOT NULL DEFAULT 0,"goldAmount" BIGINT NOT NULL DEFAULT 0,"groupPoints" BIGINT NOT NULL DEFAULT 0,"maxRedemptions" INTEGER NOT NULL DEFAULT 1,"redeemedCount" INTEGER NOT NULL DEFAULT 0,"perUserLimit" INTEGER NOT NULL DEFAULT 1,"active" BOOLEAN NOT NULL DEFAULT true,"startsAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3),"createdByTelegramId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GiftCode_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GiftCodeRedemption" ("id" TEXT NOT NULL,"giftCodeId" TEXT NOT NULL,"userId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"cashAmount" BIGINT NOT NULL DEFAULT 0,"goldAmount" BIGINT NOT NULL DEFAULT 0,"groupPoints" BIGINT NOT NULL DEFAULT 0,"redeemedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GiftCodeRedemption_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AdminAuditLog" ("id" TEXT NOT NULL,"actorTelegramId" TEXT NOT NULL,"action" TEXT NOT NULL,"targetType" TEXT NOT NULL,"targetId" TEXT NOT NULL,"reason" TEXT,"metadata" JSONB,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AdminAuditLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "GiftCode_code_key" ON "GiftCode"("code"); CREATE INDEX "GiftCode_active_startsAt_expiresAt_idx" ON "GiftCode"("active","startsAt","expiresAt");
CREATE UNIQUE INDEX "GiftCodeRedemption_idempotencyKey_key" ON "GiftCodeRedemption"("idempotencyKey"); CREATE UNIQUE INDEX "GiftCodeRedemption_giftCodeId_userId_key" ON "GiftCodeRedemption"("giftCodeId","userId"); CREATE INDEX "GiftCodeRedemption_userId_redeemedAt_idx" ON "GiftCodeRedemption"("userId","redeemedAt");
CREATE UNIQUE INDEX "AdminAuditLog_idempotencyKey_key" ON "AdminAuditLog"("idempotencyKey"); CREATE INDEX "AdminAuditLog_actorTelegramId_createdAt_idx" ON "AdminAuditLog"("actorTelegramId","createdAt"); CREATE INDEX "AdminAuditLog_targetType_targetId_createdAt_idx" ON "AdminAuditLog"("targetType","targetId","createdAt");
ALTER TABLE "GiftCodeRedemption" ADD CONSTRAINT "GiftCodeRedemption_giftCodeId_fkey" FOREIGN KEY ("giftCodeId") REFERENCES "GiftCode"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "GiftCodeRedemption" ADD CONSTRAINT "GiftCodeRedemption_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;